const CLASS_TO_COUNT = {
  1: "road",
  2: "lm_solid",
  3: "lm_dashed",
};

const countDiceScore = (groundTruth, prediction) => {
  const stats = {};
  
  Object.keys(CLASS_TO_COUNT).forEach((classId) => {
    stats[classId] = { 
      name: CLASS_TO_COUNT[classId], 
      tp: 0, 
      fp: 0, 
      fn: 0, 
      dice: 0
    };
  });

  const height = groundTruth.length;
  const width = groundTruth[0].length;

  // Iterate through each pixel
  for (let i = 0; i < height; i++) {
    for (let j = 0; j < width; j++) {
      const gtVal = groundTruth[i][j];
      const predVal = prediction[i][j];

      Object.keys(CLASS_TO_COUNT).forEach((key) => {
        const classId = Number(key);
        const isGtClass = (gtVal === classId);
        const isPredClass = (predVal === classId);

        if (isGtClass && isPredClass) {
          stats[classId].tp++;
        } else if (!isGtClass && isPredClass) {
          stats[classId].fp++;
        } else if (isGtClass && !isPredClass) {
          stats[classId].fn++;
        }
      });
    }
  }

  Object.keys(stats).forEach((key) => {
    const { tp, fp, fn, name } = stats[key];
    
    const denominator = (2 * tp) + fp + fn;
    
    stats[key].dice = denominator === 0 ? 0 : (2 * tp) / denominator;
  });

  return stats;
};

const result = countDiceScore(GROUND_TRUTH_MASK, PREDICTION_MASK);
